/* ---------------- persistência no navegador ---------------- */
// Cada tela guarda o que foi preenchido no próprio navegador. Além de não
// perder o trabalho ao voltar para o menu, é isso que permite os Bastidores
// compararem os designados com o Cartão de Designações e com A Sentinela.
const CHAVE_SALVA = "gerenciador-documentos:";

function leSalvo(chave, inicial) {
  try {
    const bruto = window.localStorage.getItem(CHAVE_SALVA + chave);
    if (!bruto) return inicial;
    const dados = JSON.parse(bruto);
    return dados && typeof dados === "object" ? dados : inicial;
  } catch (e) {
    return inicial;
  }
}

function useEstadoSalvo(chave, inicial) {
  const [dados, setDados] = useState(() => leSalvo(chave, inicial));
  useEffect(() => {
    try {
      window.localStorage.setItem(CHAVE_SALVA + chave, JSON.stringify(dados));
    } catch (e) {
      /* navegador sem espaço ou em modo privado: seguimos sem salvar */
    }
  }, [chave, dados]);
  return [dados, setDados];
}

/* ---------------- ÍCONES (SVG de linha, estilo jw.org) ---------------- */
function Icone({ nome, size = 40, color = TEMPLATE.azul }) {
  const p = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: color, strokeWidth: 1.6, strokeLinecap: "round", strokeLinejoin: "round" };
  switch (nome) {
    case "microfone": return (<svg {...p}><rect x="9" y="2" width="6" height="12" rx="3" /><path d="M5 10a7 7 0 0 0 14 0" /><line x1="12" y1="19" x2="12" y2="22" /><line x1="8" y1="22" x2="16" y2="22" /></svg>);
    case "livro": return (<svg {...p}><path d="M12 5v15" /><path d="M12 5C10 3.5 6.5 3.5 4 4v14c2.5-.5 6-.5 8 1 2-1.5 5.5-1.5 8-1V4c-2.5-.5-6-.5-8 1Z" /></svg>);
    case "cracha": return (<svg {...p}><rect x="4" y="3" width="16" height="18" rx="2" /><circle cx="12" cy="10" r="2.5" /><path d="M8 17c0-2 1.8-3 4-3s4 1 4 3" /><line x1="9" y1="3" x2="15" y2="3" /></svg>);
    case "calendario": return (<svg {...p}><rect x="3" y="5" width="18" height="16" rx="2" /><line x1="3" y1="9" x2="21" y2="9" /><line x1="8" y1="3" x2="8" y2="6" /><line x1="16" y1="3" x2="16" y2="6" /><circle cx="8" cy="13" r="0.8" fill={color} /><circle cx="12" cy="13" r="0.8" fill={color} /><circle cx="16" cy="13" r="0.8" fill={color} /><circle cx="8" cy="17" r="0.8" fill={color} /><circle cx="12" cy="17" r="0.8" fill={color} /></svg>);
    case "pessoas": return (<svg {...p}><circle cx="9" cy="8" r="3" /><circle cx="17" cy="9" r="2.2" /><path d="M3 20c0-3.3 2.7-5 6-5s6 1.7 6 5" /><path d="M15 20c0-2 .8-3.4 2.5-4" /></svg>);
    case "engrenagem": return (<svg {...p}><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.9.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.9l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.9.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.9-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.9V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1Z" /></svg>);
    case "sino": return (<svg {...p} strokeWidth="1.8"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9" /><path d="M13.7 21a2 2 0 0 1-3.4 0" /></svg>);
    case "voltar": return (<svg {...p} strokeWidth="2"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>);
    default: return null;
  }
}

