/* ====================== TELA DISCURSO PÚBLICO ====================== */
function normaliza(s) { return (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, ""); }
function achaPalavrasChave(texto) { const t = normaliza(texto); return PALAVRAS_CHAVE.filter((p) => t.includes(normaliza(p))); }
const MESES = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
function ehData(linha) { const t = (linha || "").trim(); if (/^\d{1,2}\/\d{1,2}(\/\d{2,4})?\s*$/.test(t)) return true; const tn = normaliza(t); if (/^\d{1,2}\s+de\s+/.test(tn) && MESES.some((m) => tn.includes(normaliza(m)))) return true; return false; }
function realceSugerido(texto) { const t = normaliza(texto); if (t.includes("superintendente") || t.includes("visita")) return "amarelo"; if (t.includes("congresso") || t.includes("assembleia")) return "rosa"; return "nenhum"; }
function processarTexto(texto) {
  const linhas = texto.split(/\r?\n/).map((l) => l.trim()); const blocos = []; let i = 0;
  while (i < linhas.length) {
    if (!linhas[i]) { i++; continue; }
    if (ehData(linhas[i])) { const data = linhas[i]; i++; while (i < linhas.length && !linhas[i]) i++;
      let tema = "", subtema = ""; if (i < linhas.length && !ehData(linhas[i])) { tema = linhas[i]; i++; }
      if (i < linhas.length && linhas[i] && !ehData(linhas[i])) { subtema = linhas[i]; i++; }
      blocos.push({ id: Date.now() + Math.random(), data, tema, subtema, realce: realceSugerido(tema + " " + subtema) });
    } else { i++; }
  }
  return blocos;
}

const DADOS_INICIAIS = {
  titulo: "Discurso Público", mesAno: "Agosto/2026", congregacao: "Congregação Parque Scaffid",
  linhas: [
    { id: 1, data: "01/08", tema: "Os valores de quem você preza?", subtema: "", realce: "nenhum" },
    { id: 2, data: "08/08", tema: "Tudo o que Deus nos pede é para o nosso bem", subtema: "", realce: "nenhum" },
    { id: 3, data: "15/08", tema: "Somos consolados em todas as nossas tribulações", subtema: "", realce: "nenhum" },
    { id: 4, data: "22/08", tema: "CONGRESSO REGIONAL — 21, 22 e 23 de agosto", subtema: "Não haverá discurso público na congregação", realce: "rosa" },
    { id: 5, data: "29/08", tema: "Você \u201ccolherá\u201d vida eterna?", subtema: "SEMANA DA VISITA DO SUPERINTENDENTE DE CIRCUITO", realce: "amarelo" },
  ],
  observacoes: [
    { id: 1, texto: "⟦29/08 — Semana de visita:⟧ nesta data teremos a visita do superintendente de circuito. Vamos nos esforçar para estar presentes com toda a família e convidar os estudantes da Bíblia e interessados." },
    { id: 2, texto: "⟦21, 22 e 23/08 — Congresso Regional:⟧ não haverá reunião no Salão do Reino nesse fim de semana. Continuemos empenhados na campanha de convites, de 03 a 20 de agosto." },
  ],
};

function TelaDiscurso({ onVoltar }) {
  const [dados, setDados] = useEstadoSalvo("discurso", DADOS_INICIAIS);
  const [aviso, setAviso] = useState(null);
  const [selLinha, setSelLinha] = useState(null);
  const [selObs, setSelObs] = useState(null);
  const [foto, setFoto] = useState(FOTO_ORIGINAL);
  const [fotoOriginalAtiva, setFotoOriginalAtiva] = useState(true);
  const inputFile = useRef(null);
  const [colado, setColado] = useState("");
  const [previa, setPrevia] = useState(null);
  const [erroParse, setErroParse] = useState("");

  function usarOriginal() { setFoto(FOTO_ORIGINAL); setFotoOriginalAtiva(true); }
  function escolherOutra(e) { const file = e.target.files && e.target.files[0]; if (!file) return; const r = new FileReader(); r.onload = (ev) => { setFoto(ev.target.result); setFotoOriginalAtiva(false); }; r.readAsDataURL(file); }
  function processar() { setErroParse(""); const b = processarTexto(colado); if (b.length === 0) { setErroParse("Não reconheci nenhuma data no texto. Verifique se cada data está numa linha e o tema na linha seguinte."); setPrevia(null); return; } setPrevia(b); }
  function aplicarPrevia() { setDados((d) => ({ ...d, linhas: previa.map((b, i) => ({ ...b, id: i + 1 })) })); setPrevia(null); setColado(""); }
  function cancelarPrevia() { setPrevia(null); }
  function editaLinha(id, campo, valor) {
    setDados((d) => ({ ...d, linhas: d.linhas.map((l) => (l.id === id ? { ...l, [campo]: valor } : l)) }));
    const enc = achaPalavrasChave(valor); const linha = dados.linhas.find((l) => l.id === id);
    if (enc.length > 0 && linha && linha.realce === "nenhum") setAviso({ linhaId: id, palavras: enc }); else if (aviso && aviso.linhaId === id) setAviso(null);
  }
  function defineRealce(id, cor) { setDados((d) => ({ ...d, linhas: d.linhas.map((l) => (l.id === id ? { ...l, realce: l.realce === cor ? "nenhum" : cor } : l)) })); if (aviso && aviso.linhaId === id) setAviso(null); }
  function aceitaSugestao() { if (aviso) defineRealce(aviso.linhaId, "amarelo"); }
  function capturaSelLinha(linhaId, campo, e) { const { selectionStart: ini, selectionEnd: fim } = e.target; setSelLinha(fim > ini ? { linhaId, campo, ini, fim } : null); }
  function destacaTrechoLinha() { if (!selLinha) return; const { linhaId, campo, ini, fim } = selLinha; setDados((d) => ({ ...d, linhas: d.linhas.map((l) => { if (l.id !== linhaId) return l; const v = l[campo] || ""; return { ...l, [campo]: v.slice(0, ini) + "⟦" + v.slice(ini, fim) + "⟧" + v.slice(fim) }; }) })); setSelLinha(null); }
  function limpaTrechosLinha(id) { setDados((d) => ({ ...d, linhas: d.linhas.map((l) => (l.id === id ? { ...l, tema: (l.tema || "").replace(/[⟦⟧]/g, ""), subtema: (l.subtema || "").replace(/[⟦⟧]/g, "") } : l)) })); }
  function addTema() { setDados((d) => ({ ...d, linhas: [...d.linhas, { id: Date.now(), data: "", tema: "", subtema: "", realce: "nenhum" }] })); }
  function removeTema(id) { setDados((d) => ({ ...d, linhas: d.linhas.filter((l) => l.id !== id) })); }
  function editaObs(id, valor) { setDados((d) => ({ ...d, observacoes: d.observacoes.map((o) => (o.id === id ? { ...o, texto: valor } : o)) })); }
  function addObs() { setDados((d) => ({ ...d, observacoes: [...d.observacoes, { id: Date.now(), texto: "" }] })); }
  function removeObs(id) { setDados((d) => ({ ...d, observacoes: d.observacoes.filter((o) => o.id !== id) })); }
  function capturaSelObs(obsId, e) { const { selectionStart: ini, selectionEnd: fim } = e.target; setSelObs(fim > ini ? { obsId, ini, fim } : null); }
  function destacaObs() { if (!selObs) return; const { obsId, ini, fim } = selObs; setDados((d) => ({ ...d, observacoes: d.observacoes.map((o) => { if (o.id !== obsId) return o; const v = o.texto || ""; return { ...o, texto: v.slice(0, ini) + "⟦" + v.slice(ini, fim) + "⟧" + v.slice(fim) }; }) })); setSelObs(null); }

  return (
    <div style={S.page}>
      <header style={S.appbar}>
        <button style={S.voltar} onClick={onVoltar}><Icone nome="voltar" size={18} color="#fff" /> Voltar ao menu principal</button>
        <div style={{ marginLeft: 14 }}>
          <div style={S.brandTitle}>Discurso Público</div>
          <div style={S.brandSub}>Congregação Parque Scaffid</div>
        </div>
        <div style={S.appbarTag}>Validação</div>
      </header>

      <div style={S.fotoBar}>
        <img src={foto} alt="Foto do orador" style={S.fotoThumb} />
        <div style={S.fotoInfo}><div style={S.fotoTitulo}>Foto do orador</div><div style={S.fotoStatus}>{fotoOriginalAtiva ? "Usando a imagem original do documento" : "Usando uma imagem escolhida por você"}</div></div>
        <div style={S.fotoAcoes}>
          <button style={{ ...S.btnFoto, ...(fotoOriginalAtiva ? S.btnFotoOn : {}) }} onClick={usarOriginal}>Manter original</button>
          <button style={S.btnFoto} onClick={() => inputFile.current && inputFile.current.click()}>Escolher outra imagem</button>
          <input ref={inputFile} type="file" accept="image/*" onChange={escolherOutra} style={{ display: "none" }} />
        </div>
      </div>

      <div style={S.grid} className="grid">
        <section style={S.editor}>
          <div style={S.wpp}>
            <div style={S.wppHead}><span style={S.wppTitulo}>Colar do WhatsApp</span><span style={S.wppDica}>Cole o texto do mês: cada data numa linha e o tema na linha seguinte.</span></div>
            <textarea style={S.wppArea} rows={6} value={colado} placeholder={"01/08\nOs valores de quem você preza?\n08/08\nTudo o que Deus nos pede é para o nosso bem\n..."} onChange={(e) => setColado(e.target.value)} />
            <div style={S.wppFooter}>
              <button style={S.btnProcessar} onClick={processar} disabled={!colado.trim()}>Processar</button>
              {colado && <button style={S.btnGhostAlt} onClick={() => { setColado(""); setPrevia(null); setErroParse(""); }}>Limpar</button>}
              {erroParse && <span style={S.erro}>{erroParse}</span>}
            </div>
            {previa && (
              <div style={S.previaBox}>
                <div style={S.previaTitulo}>Reconheci {previa.length} discurso(s). Isto vai substituir os quadros atuais.</div>
                <table style={S.previaTable}><thead><tr><th style={S.previaTh}>Data</th><th style={S.previaTh}>Tema</th><th style={S.previaTh}>Realce</th></tr></thead>
                  <tbody>{previa.map((b, i) => (<tr key={i}><td style={S.previaTd}>{b.data}</td><td style={S.previaTd}>{b.tema}{b.subtema ? <div style={{ color: "#777", fontSize: 11 }}>{b.subtema}</div> : null}</td><td style={S.previaTd}>{b.realce === "nenhum" ? "—" : b.realce}</td></tr>))}</tbody>
                </table>
                <div style={S.previaBtns}><button style={S.btnSim} onClick={aplicarPrevia}>Substituir quadros</button><button style={S.btnNao} onClick={cancelarPrevia}>Cancelar</button></div>
              </div>
            )}
          </div>

          <h2 style={S.h2}>Dados do mês</h2>
          <div style={S.field}><label style={S.lab}>Mês / Ano</label><input style={S.input} value={dados.mesAno} onChange={(e) => setDados({ ...dados, mesAno: e.target.value })} /></div>

          <h3 style={S.h3}>Discursos</h3>
          {dados.linhas.map((l) => {
            const kws = achaPalavrasChave((l.tema || "") + " " + (l.subtema || "")); const marcada = l.realce !== "nenhum";
            return (
              <div key={l.id} style={{ ...S.card, ...(marcada ? S.cardMarcada : {}) }}>
                <div style={S.cardTop}>
                  <input style={S.dataInput} value={l.data} onChange={(e) => editaLinha(l.id, "data", e.target.value)} aria-label="Data" />
                  <div style={S.cardActions}>
                    <button style={{ ...S.btnCor, ...(l.realce === "amarelo" ? S.btnCorOnAmarelo : {}) }} onClick={() => defineRealce(l.id, "amarelo")} title="Fundo amarelo · tema negrito vinho · subtítulo negrito dourado"><span style={{ ...S.swatch, background: TEMPLATE.amareloBg, borderColor: "#d9c34e" }} /> Amarelo</button>
                    <button style={{ ...S.btnCor, ...(l.realce === "rosa" ? S.btnCorOnRosa : {}) }} onClick={() => defineRealce(l.id, "rosa")} title="Fundo rosa · tema itálico negrito vinho · subtítulo idem"><span style={{ ...S.swatch, background: TEMPLATE.rosaClaro, borderColor: "#d8a7a7" }} /> Rosa</button>
                  </div>
                </div>
                <textarea style={S.area} rows={2} value={l.tema} onSelect={(e) => capturaSelLinha(l.id, "tema", e)} onChange={(e) => editaLinha(l.id, "tema", e.target.value)} aria-label="Tema" />
                <textarea style={{ ...S.area, ...S.areaSub }} rows={1} placeholder="Subtítulo (opcional)" value={l.subtema} onSelect={(e) => capturaSelLinha(l.id, "subtema", e)} onChange={(e) => editaLinha(l.id, "subtema", e.target.value)} aria-label="Subtítulo" />
                <div style={S.cardFooter}>
                  <button style={{ ...S.btnGhost, opacity: selLinha && selLinha.linhaId === l.id ? 1 : 0.4 }} disabled={!(selLinha && selLinha.linhaId === l.id)} onClick={destacaTrechoLinha} title="Selecione um trecho e clique para pintá-lo de amarelo">Destacar seleção</button>
                  {(l.tema.includes("⟦") || l.subtema.includes("⟦")) && (<button style={S.btnGhostAlt} onClick={() => limpaTrechosLinha(l.id)}>Limpar trechos</button>)}
                  {kws.length > 0 && <span style={S.kwTag}>palavra-chave: {kws.join(", ")}</span>}
                  <button style={S.btnRemover} onClick={() => removeTema(l.id)}>Remover tema</button>
                </div>
                {aviso && aviso.linhaId === l.id && (
                  <div style={S.sugestao} role="status">Detectei <strong>{aviso.palavras.join(", ")}</strong>. Marcar esta linha em amarelo?
                    <div style={S.sugestaoBtns}><button style={S.btnSim} onClick={aceitaSugestao}>Marcar</button><button style={S.btnNao} onClick={() => setAviso(null)}>Agora não</button></div>
                  </div>
                )}
              </div>
            );
          })}
          <button style={S.btnAdd} onClick={addTema}>+ Adicionar tema</button>

          <h3 style={S.h3}>Observações importantes</h3>
          <p style={S.hint}>Escreva as mudanças do mês. Selecione o início da informação e use <em>Destacar em vinho</em> para dar ênfase.</p>
          {dados.observacoes.map((o) => (
            <div key={o.id} style={S.obsCard}>
              <textarea style={S.obsArea} rows={3} value={o.texto} placeholder="Digite a observação…" onSelect={(e) => capturaSelObs(o.id, e)} onChange={(e) => editaObs(o.id, e.target.value)} />
              <div style={S.cardFooter}>
                <button style={{ ...S.btnVinho, opacity: selObs && selObs.obsId === o.id ? 1 : 0.4 }} disabled={!(selObs && selObs.obsId === o.id)} onClick={destacaObs} title="Selecione um trecho e clique para deixá-lo em vinho + negrito">Destacar em vinho</button>
                {o.texto.includes("⟦") && (<button style={S.btnGhostAlt} onClick={() => editaObs(o.id, o.texto.replace(/[⟦⟧]/g, ""))}>Limpar</button>)}
                <button style={S.btnRemover} onClick={() => removeObs(o.id)}>Remover</button>
              </div>
            </div>
          ))}
          <button style={S.btnAdd} onClick={addObs}>+ Adicionar observação</button>
        </section>

        <section style={S.previewWrap}><h2 style={S.h2}>Pré-visualização</h2><Preview dados={dados} foto={foto} /></section>
      </div>
    </div>
  );
}

function comMarcaTexto(texto) { return String(texto || "").split(/(⟦[^⟧]*⟧)/g).map((p, i) => p.startsWith("⟦") && p.endsWith("⟧") ? <mark key={i} style={{ background: TEMPLATE.trecho, padding: "0 1px" }}>{p.slice(1, -1)}</mark> : <span key={i}>{p}</span>); }
function comVinho(texto) { return String(texto || "").split(/(⟦[^⟧]*⟧)/g).map((p, i) => p.startsWith("⟦") && p.endsWith("⟧") ? <strong key={i} style={{ color: TEMPLATE.vinho }}>{p.slice(1, -1)}</strong> : <span key={i}>{p}</span>); }
function estiloTema(realce) { if (realce === "amarelo") return { color: TEMPLATE.vinho, fontWeight: 700 }; if (realce === "rosa") return { color: TEMPLATE.vinho, fontWeight: 700, fontStyle: "italic" }; return { color: "#222" }; }
function estiloSub(realce) { if (realce === "amarelo") return { color: TEMPLATE.dourado, fontWeight: 700, fontSize: 10, textTransform: "uppercase" }; if (realce === "rosa") return { color: TEMPLATE.vinho, fontWeight: 700, fontStyle: "italic", fontSize: 10 }; return { color: "#444", fontSize: 10 }; }

function Preview({ dados, foto }) {
  return (
    <div style={PV.frameOuter}><div style={PV.frameInner}>
      <div style={PV.foto}>{foto ? <img src={foto} alt="Orador" style={PV.fotoImg} /> : <div style={PV.fotoPlaceholder}>sem foto</div>}</div>
      <div style={PV.titulo}>{dados.titulo}</div><div style={PV.titulo}>{dados.mesAno}</div><div style={PV.sub}>{dados.congregacao}</div>
      <table style={PV.table}><thead><tr><th style={{ ...PV.th, width: "24%" }}>Data</th><th style={PV.th}>Tema</th></tr></thead>
        <tbody>{dados.linhas.map((l) => { const bg = l.realce === "amarelo" ? TEMPLATE.amareloBg : l.realce === "rosa" ? TEMPLATE.rosaClaro : "#fff"; return (
          <tr key={l.id} style={{ background: bg }}><td style={{ ...PV.tdData, color: l.realce !== "nenhum" ? TEMPLATE.vinho : "#222" }}>{l.data}</td>
            <td style={PV.tdTema}><div style={estiloTema(l.realce)}>{comMarcaTexto(l.tema)}</div>{l.subtema ? <div style={estiloSub(l.realce)}>{comMarcaTexto(l.subtema)}</div> : null}</td></tr>); })}</tbody>
      </table>
      <div style={PV.obsTitulo}>OBSERVAÇÕES IMPORTANTES</div><div style={PV.regua} />
      {dados.observacoes.map((o) => (<div key={o.id} style={PV.obsItem}><span style={PV.bullet}>•</span><span>{comVinho(o.texto)}</span></div>))}
    </div></div>
  );
}


/* ====================== TELA REUNIÃO A SENTINELA ====================== */
const MESES_S = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
function ehDataCabecalhoS(l) {
  const t = (l || "").trim();
  if (/^\d{1,2}\s*[–\-]\s*[A-Za-zçÇ]+\s*[–\-]\s*\d{4}/.test(t)) return true;
  if (/^\d{1,2}\/\d{1,2}(\/\d{2,4})?\s*$/.test(t)) return true;
  const tn = normaliza(t);
  if (/^\d{1,2}\s+de\s+/.test(tn) && MESES_S.some((m) => tn.includes(normaliza(m)))) return true;
  return false;
}
const CAMPOS_S = {
  "presidente": "presidente", "oracao inicial": "oracaoInicial",
  "estudo da revista a sentinela": "estudo", "estudo da revista a sentinela (resumo)": "estudo",
  "leitor do estudo da revista": "leitor",
  "oracao final (caso o orador nao fique)": "oracaoFinal", "oracao final": "oracaoFinal",
};
function achaCampoS(rotulo) {
  const r = normaliza(rotulo);
  if (CAMPOS_S[r]) return CAMPOS_S[r];
  for (const k in CAMPOS_S) { if (r.startsWith(k.slice(0, 12))) return CAMPOS_S[k]; }
  return null;
}
function processarSentinela(texto) {
  const linhas = texto.split(/\r?\n/).map((l) => l.trim()).filter((x) => x !== "");
  const blocos = []; let atual = null;
  for (const linha of linhas) {
    if (ehDataCabecalhoS(linha)) { atual = { data: linha, campos: {} }; blocos.push(atual); continue; }
    if (!atual) continue;
    const partes = linha.split(/:\s*/);
    if (partes.length >= 2) { const campo = achaCampoS(partes[0]); if (campo) atual.campos[campo] = partes.slice(1).join(": "); }
  }
  return blocos;
}
function tipoBlocoPorData(data, campos) {
  const t = normaliza(data + " " + Object.values(campos || {}).join(" "));
  if (t.includes("congresso")) return "congresso";
  if (t.includes("visita") || t.includes("superintendente")) return "visita";
  return "normal";
}

const SENTINELA_INICIAL = {
  titulo: "Reuniões de Final de Semana", congregacao: "Congregação Parque Scaffid", mesAno: "Agosto/2026",
  blocos: [
    { id: 1, tipo: "normal", data: "01 – Agosto – 2026", presidente: "Ricardo Nery", oracaoInicial: "Ricardo Nery", estudo: "Ademir", leitor: "Lucas Soares", oracaoFinal: "Erik" },
    { id: 2, tipo: "normal", data: "08 – Agosto – 2026", presidente: "Dorival", oracaoInicial: "Dorival", estudo: "Rodrigo", leitor: "Walter", oracaoFinal: "Walter" },
    { id: 3, tipo: "normal", data: "15 – Agosto – 2026", presidente: "Daniel", oracaoInicial: "Daniel", estudo: "Ademir", leitor: "Roberto", oracaoFinal: "João Bizerra" },
    { id: 4, tipo: "congresso", data: "22 – Agosto – 2026", aviso: "CONGRESSO REGIONAL — 21, 22 e 23 de agosto", subAviso: "Não haverá reunião no Salão do Reino neste fim de semana" },
    { id: 5, tipo: "visita", data: "29 – Agosto – 2026", subtitulo: "VISITA DO SUPERINTENDENTE DE CIRCUITO", presidente: "Anderson", oracaoInicial: "Anderson", discursoInicial: "Você \u201ccolherá\u201d vida eterna?", discursoInicialResp: "Rodrigo Silva", estudo: "Ademir", discursoFinal: "O que vocês se tornaram!", discursoFinalResp: "Superintendente de Circuito", oracaoFinal: "Rodrigo Silva" },
  ],
  observacoes: [
    { id: 1, texto: "⟦22/08 — Congresso Regional:⟧ não haverá reunião na congregação nos dias 21, 22 e 23. Estejamos presentes nos três dias do programa." },
    { id: 2, texto: "⟦29/08 — Visita do superintendente de circuito:⟧ o Estudo de A Sentinela será em forma de resumo e o discurso final ficará a cargo do irmão viajante. Vamos convidar os estudantes da Bíblia, os interessados e os irmãos inativos." },
    { id: 3, texto: "⟦Designados:⟧ em caso de impedimento, avise o presidente da reunião com antecedência para que haja tempo de providenciar substituto." },
  ],
};

function TelaSentinela({ onVoltar }) {
  const [dados, setDados] = useEstadoSalvo("sentinela", SENTINELA_INICIAL);
  const [selObs, setSelObs] = React.useState(null);
  const [colado, setColado] = React.useState("");
  const [previa, setPrevia] = React.useState(null);
  const [erroParse, setErroParse] = React.useState("");

  function editaBloco(id, campo, valor) { setDados((d) => ({ ...d, blocos: d.blocos.map((b) => (b.id === id ? { ...b, [campo]: valor } : b)) })); }
  function mudaTipo(id, novoTipo) { setDados((d) => ({ ...d, blocos: d.blocos.map((b) => (b.id === id ? { ...b, tipo: novoTipo } : b)) })); }
  function addSemana() { setDados((d) => ({ ...d, blocos: [...d.blocos, { id: Date.now(), tipo: "normal", data: "", presidente: "", oracaoInicial: "", estudo: "", leitor: "", oracaoFinal: "" }] })); }
  function removeSemana(id) { setDados((d) => ({ ...d, blocos: d.blocos.filter((b) => b.id !== id) })); }
  function editaObs(id, valor) { setDados((d) => ({ ...d, observacoes: d.observacoes.map((o) => (o.id === id ? { ...o, texto: valor } : o)) })); }
  function addObs() { setDados((d) => ({ ...d, observacoes: [...d.observacoes, { id: Date.now(), texto: "" }] })); }
  function removeObs(id) { setDados((d) => ({ ...d, observacoes: d.observacoes.filter((o) => o.id !== id) })); }
  function capturaSelObs(obsId, e) { const { selectionStart: ini, selectionEnd: fim } = e.target; setSelObs(fim > ini ? { obsId, ini, fim } : null); }
  function destacaObs() { if (!selObs) return; const { obsId, ini, fim } = selObs; setDados((d) => ({ ...d, observacoes: d.observacoes.map((o) => { if (o.id !== obsId) return o; const v = o.texto || ""; return { ...o, texto: v.slice(0, ini) + "⟦" + v.slice(ini, fim) + "⟧" + v.slice(fim) }; }) })); setSelObs(null); }

  function processar() {
    setErroParse("");
    const brutos = processarSentinela(colado);
    if (brutos.length === 0) { setErroParse("Não reconheci nenhum bloco. Verifique se cada semana começa com a data (ex.: 01 – Agosto – 2026) e as designações no formato \"Presidente: Nome\"."); setPrevia(null); return; }
    const blocos = brutos.map((b, i) => {
      const tipo = tipoBlocoPorData(b.data, b.campos);
      return { id: i + 1, tipo, data: b.data, ...b.campos };
    });
    setPrevia(blocos);
  }
  function aplicarPrevia() { setDados((d) => ({ ...d, blocos: previa })); setPrevia(null); setColado(""); }

  return (
    <div style={S.page}>
      <header style={S.appbar}>
        <button style={S.voltar} onClick={onVoltar}><Icone nome="voltar" size={18} color="#fff" /> Voltar ao menu principal</button>
        <div style={{ marginLeft: 14 }}>
          <div style={S.brandTitle}>Reunião A Sentinela</div>
          <div style={S.brandSub}>Congregação Parque Scaffid</div>
        </div>
        <div style={S.appbarTag}>Validação</div>
      </header>

      <div style={S.grid} className="grid">
        <section style={S.editor}>
          <div style={S.wpp}>
            <div style={S.wppHead}><span style={S.wppTitulo}>Colar do WhatsApp</span><span style={S.wppDica}>Cole o texto: cada semana começa com a data e as designações no formato "Presidente: Nome".</span></div>
            <textarea style={S.wppArea} rows={6} value={colado} placeholder={"01 – Agosto – 2026\nPresidente: Ricardo Nery\nOração Inicial: Ricardo Nery\nEstudo da Revista A Sentinela: Ademir\nLeitor do Estudo da Revista: Lucas Soares\nOração Final: Erik"} onChange={(e) => setColado(e.target.value)} />
            <div style={S.wppFooter}>
              <button style={S.btnProcessar} onClick={processar} disabled={!colado.trim()}>Processar</button>
              {colado && <button style={S.btnGhostAlt} onClick={() => { setColado(""); setPrevia(null); setErroParse(""); }}>Limpar</button>}
              {erroParse && <span style={S.erro}>{erroParse}</span>}
            </div>
            {previa && (
              <div style={S.previaBox}>
                <div style={S.previaTitulo}>Reconheci {previa.length} semana(s). Isto vai substituir os blocos atuais.</div>
                <table style={S.previaTable}><thead><tr><th style={S.previaTh}>Data</th><th style={S.previaTh}>Tipo</th><th style={S.previaTh}>Presidente</th></tr></thead>
                  <tbody>{previa.map((b, i) => (<tr key={i}><td style={S.previaTd}>{b.data}</td><td style={S.previaTd}>{b.tipo}</td><td style={S.previaTd}>{b.presidente || "—"}</td></tr>))}</tbody>
                </table>
                <div style={S.previaBtns}><button style={S.btnSim} onClick={aplicarPrevia}>Substituir blocos</button><button style={S.btnNao} onClick={() => setPrevia(null)}>Cancelar</button></div>
              </div>
            )}
          </div>

          <h2 style={S.h2}>Dados do mês</h2>
          <div style={S.field}><label style={S.lab}>Mês / Ano</label><input style={S.input} value={dados.mesAno} onChange={(e) => setDados({ ...dados, mesAno: e.target.value })} /></div>

          <h3 style={S.h3}>Semanas</h3>
          {dados.blocos.map((b) => (
            <div key={b.id} style={{ ...S.card, ...(b.tipo === "congresso" ? { borderColor: "#e0b8b8" } : b.tipo === "visita" ? { borderColor: "#e7d48a" } : {}) }}>
              <div style={S.cardTop}>
                <input style={{ ...S.input, fontWeight: 700, maxWidth: 200 }} value={b.data} onChange={(e) => editaBloco(b.id, "data", e.target.value)} aria-label="Data" />
                <select style={S.tipoSelect} value={b.tipo} onChange={(e) => mudaTipo(b.id, e.target.value)} aria-label="Tipo de semana">
                  <option value="normal">Semana Normal</option>
                  <option value="assembleia">Assembleia</option>
                  <option value="congresso">Congresso</option>
                  <option value="visita">Visita do SC</option>
                </select>
                <button style={S.btnRemoverSemana} onClick={() => removeSemana(b.id)} title="Remover esta semana">Remover</button>
              </div>

              {(b.tipo === "congresso" || b.tipo === "assembleia") && (
                <div style={S.campos}>
                  <CampoS label="Aviso" v={b.aviso} on={(x) => editaBloco(b.id, "aviso", x)} />
                  <CampoS label="Subtítulo" v={b.subAviso} on={(x) => editaBloco(b.id, "subAviso", x)} />
                </div>
              )}

              {b.tipo === "normal" && (
                <div style={S.campos}>
                  <CampoS label="Presidente" v={b.presidente} on={(x) => editaBloco(b.id, "presidente", x)} />
                  <CampoS label="Oração Inicial" v={b.oracaoInicial} on={(x) => editaBloco(b.id, "oracaoInicial", x)} />
                  <CampoS label="Estudo da Revista A Sentinela" v={b.estudo} on={(x) => editaBloco(b.id, "estudo", x)} />
                  <CampoS label="Leitor do Estudo da Revista" v={b.leitor} on={(x) => editaBloco(b.id, "leitor", x)} />
                  <CampoS label="Oração Final (caso o orador não fique)" v={b.oracaoFinal} on={(x) => editaBloco(b.id, "oracaoFinal", x)} destaque />
                </div>
              )}
              {b.tipo === "visita" && (
                <div style={S.campos}>
                  <CampoS label="Subtítulo" v={b.subtitulo} on={(x) => editaBloco(b.id, "subtitulo", x)} />
                  <CampoS label="Presidente" v={b.presidente} on={(x) => editaBloco(b.id, "presidente", x)} />
                  <CampoS label="Oração Inicial" v={b.oracaoInicial} on={(x) => editaBloco(b.id, "oracaoInicial", x)} />
                  <CampoS label="Discurso inicial — tema" v={b.discursoInicial} on={(x) => editaBloco(b.id, "discursoInicial", x)} />
                  <CampoS label="Discurso inicial — responsável" v={b.discursoInicialResp} on={(x) => editaBloco(b.id, "discursoInicialResp", x)} />
                  <CampoS label="Estudo da Revista (resumo)" v={b.estudo} on={(x) => editaBloco(b.id, "estudo", x)} />
                  <CampoS label="Discurso final — tema" v={b.discursoFinal} on={(x) => editaBloco(b.id, "discursoFinal", x)} />
                  <CampoS label="Discurso final — responsável" v={b.discursoFinalResp} on={(x) => editaBloco(b.id, "discursoFinalResp", x)} />
                  <CampoS label="Oração Final" v={b.oracaoFinal} on={(x) => editaBloco(b.id, "oracaoFinal", x)} destaque />
                </div>
              )}
            </div>
          ))}
          <button style={S.btnAdd} onClick={addSemana}>+ Adicionar semana</button>

          <h3 style={S.h3}>Observações</h3>
          <p style={S.hint}>Selecione o início da informação e use <em>Destacar em vinho</em> para dar ênfase.</p>
          {dados.observacoes.map((o) => (
            <div key={o.id} style={S.obsCard}>
              <textarea style={S.obsArea} rows={2} value={o.texto} placeholder="Digite a observação…" onSelect={(e) => capturaSelObs(o.id, e)} onChange={(e) => editaObs(o.id, e.target.value)} />
              <div style={S.cardFooter}>
                <button style={{ ...S.btnVinho, opacity: selObs && selObs.obsId === o.id ? 1 : 0.4 }} disabled={!(selObs && selObs.obsId === o.id)} onClick={destacaObs}>Destacar em vinho</button>
                {o.texto.includes("⟦") && (<button style={S.btnGhostAlt} onClick={() => editaObs(o.id, o.texto.replace(/[⟦⟧]/g, ""))}>Limpar</button>)}
                <button style={S.btnRemover} onClick={() => removeObs(o.id)}>Remover</button>
              </div>
            </div>
          ))}
          <button style={S.btnAdd} onClick={addObs}>+ Adicionar observação</button>
        </section>

        <section style={S.previewWrap}><h2 style={S.h2}>Pré-visualização</h2><PreviewSentinela dados={dados} /></section>
      </div>
    </div>
  );
}

function CampoS({ label, v, on, destaque }) {
  return (
    <div style={SS.campoRow}>
      <label style={{ ...SS.campoLabel, ...(destaque ? { color: TEMPLATE.vinho, fontWeight: 700 } : {}) }}>{label}</label>
      <input style={SS.campoInput} value={v || ""} onChange={(e) => on(e.target.value)} />
    </div>
  );
}

function PreviewSentinela({ dados }) {
  return (
    <div style={PV.frameOuter}><div style={PV.frameInner}>
      <div style={{ textAlign: "center", color: TEMPLATE.vinho, fontWeight: 800, fontSize: 20 }}>{dados.titulo}</div>
      <div style={{ textAlign: "center", color: TEMPLATE.azul, fontWeight: 700, fontSize: 12, margin: "4px 0 6px" }}>{dados.congregacao} • {dados.mesAno}</div>
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", width: "100%", margin: "8px 0 14px" }}><img src={IMG_SENTINELA} alt="A Sentinela — Anunciando o Reino de Jeová" style={{ height: 46, width: "auto", display: "block" }} /></div>

      {dados.blocos.map((b) => {
        if (b.tipo === "congresso" || b.tipo === "assembleia") return (
          <div key={b.id} style={SP.bloco}>
            <div style={{ ...SP.cabecalho, background: TEMPLATE.vinho }}>{b.data}</div>
            <div style={{ background: TEMPLATE.rosaClaro, padding: "12px 10px", textAlign: "center" }}>
              <div style={{ color: TEMPLATE.vinho, fontWeight: 700, fontSize: 12 }}>{b.aviso}</div>
              <div style={{ color: TEMPLATE.vinho, fontStyle: "italic", fontSize: 11, marginTop: 2 }}>{b.subAviso}</div>
            </div>
          </div>
        );
        if (b.tipo === "visita") return (
          <div key={b.id} style={SP.bloco}>
            <div style={{ ...SP.cabecalho, background: TEMPLATE.dourado }}>{b.data}</div>
            <div style={{ background: "#FBF3D5", color: TEMPLATE.dourado, fontWeight: 700, fontSize: 11, textAlign: "center", padding: "5px", textTransform: "uppercase" }}>{b.subtitulo}</div>
            <LinhaSP rotulo="Presidente" valor={b.presidente} zebra={0} />
            <LinhaSP rotulo="Oração Inicial" valor={b.oracaoInicial} zebra={1} />
            <LinhaSP rotulo={"Discurso inicial — " + (b.discursoInicial || "")} valor={b.discursoInicialResp} zebra={0} corRotulo={TEMPLATE.dourado} negrito />
            <LinhaSP rotulo="Estudo da Revista A Sentinela (resumo)" valor={b.estudo} zebra={1} />
            <LinhaSP rotulo={"Discurso final — " + (b.discursoFinal || "")} valor={b.discursoFinalResp} zebra={0} corRotulo={TEMPLATE.dourado} negrito italicoValor />
            <LinhaSP rotulo="Oração Final" valor={b.oracaoFinal} zebra={1} corRotulo={TEMPLATE.dourado} negrito />
          </div>
        );
        return (
          <div key={b.id} style={SP.bloco}>
            <div style={{ ...SP.cabecalho, background: TEMPLATE.azul }}>{b.data}</div>
            <LinhaSP rotulo="Presidente" valor={b.presidente} zebra={0} />
            <LinhaSP rotulo="Oração Inicial" valor={b.oracaoInicial} zebra={1} />
            <LinhaSP rotulo="Estudo da Revista A Sentinela" valor={b.estudo} zebra={0} />
            <LinhaSP rotulo="Leitor do Estudo da Revista" valor={b.leitor} zebra={1} />
            <LinhaSP rotulo="Oração Final (CASO O ORADOR NÃO FIQUE)" valor={b.oracaoFinal} zebra={0} corRotulo={TEMPLATE.vinho} negrito />
          </div>
        );
      })}

      <div style={PV.obsTitulo}>OBSERVAÇÕES</div><div style={PV.regua} />
      {dados.observacoes.map((o) => (<div key={o.id} style={PV.obsItem}><span style={PV.bullet}>•</span><span>{comVinho(o.texto)}</span></div>))}
    </div></div>
  );
}
function LinhaSP({ rotulo, valor, zebra, corRotulo, negrito, italicoValor }) {
  return (
    <div style={{ display: "flex", background: zebra ? "#eef1f6" : "#fff", fontSize: 11, borderBottom: "1px solid #e3e7ee" }}>
      <div style={{ flex: 1, padding: "6px 8px", color: corRotulo || "#333", fontWeight: negrito ? 700 : 400 }}>{rotulo}</div>
      <div style={{ width: "42%", padding: "6px 8px", textAlign: "center", fontWeight: 700, fontStyle: italicoValor ? "italic" : "normal" }}>{valor}</div>
    </div>
  );
}


/* ====================== TELA CALENDÁRIO DE PREGAÇÃO ====================== */
// Paleta de cores de fundo que o Sr. Ancião pode aplicar por dia.
const CORES_DIA = [
  { nome: "Nenhuma", valor: "" },
  { nome: "Verde claro", valor: "#eaf3e4" },
  { nome: "Dourado", valor: "#f6edcf" },
  { nome: "Rosa", valor: "#f6e2e2" },
  { nome: "Azul claro", valor: "#e4edf7" },
  { nome: "Cinza", valor: "#eef0f3" },
];
const DIAS_SEMANA = ["SEGUNDA-FEIRA", "TERÇA-FEIRA", "QUARTA-FEIRA", "QUINTA-FEIRA", "SEXTA-FEIRA", "SÁBADO", "DOMINGO"];

// Gera os dias de um mês. inicioSemana: 0=segunda ... 6=domingo (dia da semana do dia 1).
function gerarDias(qtdDias, inicioSemana) {
  const dias = [];
  for (let i = 0; i < inicioSemana; i++) dias.push(null); // células vazias antes do dia 1
  for (let d = 1; d <= qtdDias; d++) dias.push({ id: d, numero: d, texto: "", cor: "" });
  while (dias.length % 7 !== 0) dias.push(null); // completa a última linha
  return dias;
}

const CALENDARIO_INICIAL = {
  titulo: "Calendário de pregação",
  congregacao: "Congregação Parque Scaffid",
  mesAno: "Agosto / 2026",
  faixaTitulo: "CAMPANHA DE CONVITES • CONGRESSO REGIONAL 2026 • 21, 22 e 23 DE AGOSTO",
  faixaSub: "Distribuição dos convites: de 01 a 20 de agosto — “Venha!” (Apocalipse 22:17)",
  mostrarFaixa: true,
  qtdDias: 31,
  inicioSemana: 5, // agosto/2026: o dia 1 cai num sábado (seg=0 ... dom=6)
  dias: [],
  notas: [
    { id: 1, tipo: "nota", texto: "*Domingo: Campo de casa em casa saindo dos locais indicados no calendário conforme seu grupo." },
    { id: 2, tipo: "nota", texto: "**Segunda-feira (“Não em casa” do dia anterior): Continuação do trabalho de campo de casa em casa, revisitando apenas as residências que não foram atendidas no dia anterior." },
    { id: 3, tipo: "nota", texto: "***Congresso Regional (21, 22 e 23 de agosto): Não haverá saídas de campo nesses três dias. Chegue com antecedência e esteja presente nos três dias, desde a canção de abertura." },
  ],
};

function TelaCalendario({ onVoltar }) {
  const inicial = React.useMemo(() => {
    const base = { ...CALENDARIO_INICIAL };
    base.dias = gerarDias(base.qtdDias, base.inicioSemana);
    return base;
  }, []);
  const [dados, setDados] = useEstadoSalvo("calendario", inicial);
  const [diaAberto, setDiaAberto] = React.useState(null);
  const [foto, setFoto] = React.useState(IMG_CALENDARIO);
  const [fotoOriginalAtiva, setFotoOriginalAtiva] = React.useState(true);
  const [selDia, setSelDia] = React.useState(null); // {numero, ini, fim}
  const [corFonte, setCorFonte] = React.useState("#c0392b");
  const inputFileCal = React.useRef(null);

  function usarFotoOriginal() { setFoto(IMG_CALENDARIO); setFotoOriginalAtiva(true); }
  function escolherFotoCal(e) { const f = e.target.files && e.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = (ev) => { setFoto(ev.target.result); setFotoOriginalAtiva(false); }; r.readAsDataURL(f); }
  function capturaSelDia(numero, e) { const { selectionStart: ini, selectionEnd: fim } = e.target; setSelDia(fim > ini ? { numero, ini, fim } : null); }

  function editaCampo(campo, valor) { setDados((d) => ({ ...d, [campo]: valor })); }
  function editaNota(id, valor) { setDados((d) => ({ ...d, notas: d.notas.map((n) => (n.id === id ? { ...n, texto: valor } : n)) })); }
  function mudaTipoNota(id, tipo) { setDados((d) => ({ ...d, notas: d.notas.map((n) => (n.id === id ? { ...n, tipo } : n)) })); }
  function addNota() { setDados((d) => ({ ...d, notas: [...d.notas, { id: Date.now(), tipo: "nota", texto: "" }] })); }
  function removeNota(id) { setDados((d) => ({ ...d, notas: d.notas.filter((n) => n.id !== id) })); }
  // Formatação de trecho no texto do dia: ⟦cor|negrito:texto⟧
  function formataTrechoDia(numero, sel, cor, negrito) {
    if (!sel || sel.numero !== numero) return;
    setDados((d) => ({ ...d, dias: d.dias.map((c) => {
      if (!c || c.numero !== numero) return c;
      const v = c.texto || ""; const trecho = v.slice(sel.ini, sel.fim);
      const flags = (cor || "") + "|" + (negrito ? "b" : "");
      return { ...c, texto: v.slice(0, sel.ini) + "⟦" + flags + ":" + trecho + "⟧" + v.slice(sel.fim) };
    }) }));
  }
  function limpaFormatoDia(numero) {
    setDados((d) => ({ ...d, dias: d.dias.map((c) => (c && c.numero === numero ? { ...c, texto: (c.texto || "").replace(/⟦[^:]*:/g, "").replace(/⟧/g, "") } : c)) }));
  }
  function regenerarGrade(qtd, inicio) {
    setDados((d) => {
      const antigos = {};
      d.dias.forEach((x) => { if (x) antigos[x.numero] = x; });
      const novos = gerarDias(qtd, inicio).map((c) => (c && antigos[c.numero] ? antigos[c.numero] : c));
      return { ...d, qtdDias: qtd, inicioSemana: inicio, dias: novos };
    });
  }
  function editaDia(numero, campo, valor) {
    setDados((d) => ({ ...d, dias: d.dias.map((c) => (c && c.numero === numero ? { ...c, [campo]: valor } : c)) }));
  }

  const linhas = [];
  for (let i = 0; i < dados.dias.length; i += 7) linhas.push(dados.dias.slice(i, i + 7));

  return (
    <div style={S.page}>
      <header style={S.appbar}>
        <button style={S.voltar} onClick={onVoltar}><Icone nome="voltar" size={18} color="#fff" /> Voltar ao menu principal</button>
        <div style={{ marginLeft: 14 }}>
          <div style={S.brandTitle}>Calendário de Pregação</div>
          <div style={S.brandSub}>Congregação Parque Scaffid</div>
        </div>
        <div style={S.appbarTag}>Validação</div>
      </header>

      <div style={S.grid} className="grid">
        <section style={S.editor}>
          <h2 style={S.h2}>Cabeçalho</h2>
          <div style={S.field}><label style={S.lab}>Mês / Ano</label><input style={S.input} value={dados.mesAno} onChange={(e) => editaCampo("mesAno", e.target.value)} /></div>

          <div style={{ ...S.fotoBar, padding: "10px 0", borderBottom: "none", marginBottom: 6 }}>
            <img src={foto} alt="Ilustração" style={S.fotoThumb} />
            <div style={S.fotoInfo}><div style={S.fotoTitulo}>Imagem do topo</div><div style={S.fotoStatus}>{fotoOriginalAtiva ? "Imagem original do documento" : "Imagem escolhida por você"}</div></div>
            <div style={S.fotoAcoes}>
              <button style={{ ...S.btnFoto, ...(fotoOriginalAtiva ? S.btnFotoOn : {}) }} onClick={usarFotoOriginal}>Manter original</button>
              <button style={S.btnFoto} onClick={() => inputFileCal.current && inputFileCal.current.click()}>Importar da galeria</button>
              <input ref={inputFileCal} type="file" accept="image/*" onChange={escolherFotoCal} style={{ display: "none" }} />
            </div>
          </div>

          <label style={{ ...S.lab, display: "flex", alignItems: "center", gap: 8, cursor: "pointer", marginBottom: 8 }}>
            <input type="checkbox" checked={dados.mostrarFaixa} onChange={(e) => editaCampo("mostrarFaixa", e.target.checked)} />
            Exibir título e subtítulo no calendário
          </label>
          {dados.mostrarFaixa && (<>
            <div style={S.field}><label style={S.lab}>Título</label><input style={S.input} value={dados.faixaTitulo} onChange={(e) => editaCampo("faixaTitulo", e.target.value)} /></div>
            <div style={S.field}><label style={S.lab}>Subtítulo</label><input style={S.input} value={dados.faixaSub} onChange={(e) => editaCampo("faixaSub", e.target.value)} /></div>
          </>)}

          <h3 style={S.h3}>Estrutura do mês</h3>
          <div style={{ display: "flex", gap: 12, alignItems: "flex-end", marginBottom: 8 }}>
            <div><label style={S.lab}>Dias no mês</label><input type="number" min="28" max="31" style={{ ...S.input, width: 90 }} value={dados.qtdDias} onChange={(e) => regenerarGrade(Number(e.target.value) || 31, dados.inicioSemana)} /></div>
            <div><label style={S.lab}>Dia 1 cai em</label>
              <select style={S.tipoSelect} value={dados.inicioSemana} onChange={(e) => regenerarGrade(dados.qtdDias, Number(e.target.value))}>
                {DIAS_SEMANA.map((d, i) => <option key={i} value={i}>{d.charAt(0) + d.slice(1).toLowerCase()}</option>)}
              </select>
            </div>
          </div>

          <h3 style={S.h3}>Dias — clique para editar</h3>
          <p style={S.hint}>Cada dia tem uma caixa de texto livre e uma cor de fundo opcional para destaque.</p>
          <div style={CAL.miniGrid}>
            {DIAS_SEMANA.map((d) => <div key={d} style={CAL.miniHead}>{d.slice(0, 3)}</div>)}
            {dados.dias.map((c, i) => (
              <div key={i} style={{ ...CAL.miniCell, background: c ? (c.cor || "#fff") : "#f7f8fa", cursor: c ? "pointer" : "default", borderColor: diaAberto === (c && c.numero) ? UI.azul : UI.borda }}
                onClick={() => c && setDiaAberto(diaAberto === c.numero ? null : c.numero)}>
                {c ? <><div style={CAL.miniNum}>{c.numero}</div><div style={CAL.miniPrev}>{c.texto ? c.texto.slice(0, 24) : ""}</div></> : null}
              </div>
            ))}
          </div>

          {diaAberto && (() => {
            const dia = dados.dias.find((c) => c && c.numero === diaAberto);
            if (!dia) return null;
            return (
              <div style={CAL.editorDia}>
                <div style={CAL.editorDiaTop}>Editando o dia <strong>{dia.numero}</strong>
                  <button style={S.btnGhostAlt} onClick={() => setDiaAberto(null)}>Fechar</button>
                </div>
                <textarea style={{ ...S.obsArea, minHeight: 120 }} value={dia.texto} placeholder={"Ex.:\nZOOM\n09:30\nCONVITES\nDirigente Rodrigo ou Filipe\nCONTINUA VILLAGE"} onSelect={(e) => capturaSelDia(dia.numero, e)} onChange={(e) => editaDia(dia.numero, "texto", e.target.value)} />

                <div style={{ fontSize: 12, color: UI.cinza, marginTop: 6, marginBottom: 4 }}>Formatar trecho selecionado:</div>
                <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                  <input type="color" value={corFonte} onChange={(e) => setCorFonte(e.target.value)} style={{ width: 34, height: 30, border: "1px solid " + UI.borda, borderRadius: 6, cursor: "pointer", padding: 0 }} title="Escolha a cor da fonte" />
                  <button style={{ ...S.btnGhost, opacity: selDia && selDia.numero === dia.numero ? 1 : 0.4 }} disabled={!(selDia && selDia.numero === dia.numero)} onClick={() => formataTrechoDia(dia.numero, selDia, corFonte, false)}>Aplicar cor</button>
                  <button style={{ ...S.btnVinho, opacity: selDia && selDia.numero === dia.numero ? 1 : 0.4 }} disabled={!(selDia && selDia.numero === dia.numero)} onClick={() => formataTrechoDia(dia.numero, selDia, corFonte, true)}>Cor + Negrito</button>
                  <button style={{ ...S.btnGhost, opacity: selDia && selDia.numero === dia.numero ? 1 : 0.4 }} disabled={!(selDia && selDia.numero === dia.numero)} onClick={() => formataTrechoDia(dia.numero, selDia, "", true)}>Só Negrito</button>
                  {dia.texto.includes("⟦") && (<button style={S.btnGhostAlt} onClick={() => limpaFormatoDia(dia.numero)}>Limpar formatação</button>)}
                </div>

                <div style={{ fontSize: 12, color: UI.cinza, marginTop: 10, marginBottom: 4 }}>Cor de fundo do dia:</div>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {CORES_DIA.map((cor) => (
                    <button key={cor.nome} onClick={() => editaDia(dia.numero, "cor", cor.valor)} title={cor.nome}
                      style={{ ...CAL.corBtn, background: cor.valor || "#fff", borderColor: dia.cor === cor.valor ? UI.azul : "#ccc", borderWidth: dia.cor === cor.valor ? 2 : 1 }}>
                      {cor.valor === "" ? "∅" : ""}
                    </button>
                  ))}
                </div>
              </div>
            );
          })()}

          <h3 style={S.h3}>Notas de rodapé</h3>
          <p style={S.hint}>Escolha se cada linha é uma nota comum ou um título (título fica vermelho e itálico).</p>
          {dados.notas.map((n) => (
            <div key={n.id} style={S.obsCard}>
              <div style={{ display: "flex", gap: 8, marginBottom: 6 }}>
                <select style={S.tipoSelect} value={n.tipo} onChange={(e) => mudaTipoNota(n.id, e.target.value)}>
                  <option value="nota">Nota</option>
                  <option value="titulo">Título</option>
                </select>
                <button style={S.btnRemover} onClick={() => removeNota(n.id)}>Remover</button>
              </div>
              <textarea style={{ ...S.obsArea, minHeight: 50 }} value={n.texto} onChange={(e) => editaNota(n.id, e.target.value)} />
            </div>
          ))}
          <button style={S.btnAdd} onClick={addNota}>+ Adicionar nota</button>
        </section>

        <section style={S.previewWrap}><h2 style={S.h2}>Pré-visualização</h2><PreviewCalendario dados={dados} linhas={linhas} foto={foto} /></section>
      </div>
    </div>
  );
}

// Renderiza texto do dia com marcadores ⟦cor|flags:texto⟧
function renderTextoDia(texto) {
  return String(texto || "").split(/(⟦[^⟧]*⟧)/g).map((p, i) => {
    if (p.startsWith("⟦") && p.endsWith("⟧")) {
      const conteudo = p.slice(1, -1);
      const sep = conteudo.indexOf(":");
      const flags = conteudo.slice(0, sep); const txt = conteudo.slice(sep + 1);
      const [cor, estilo] = flags.split("|");
      return <span key={i} style={{ color: cor || "inherit", fontWeight: estilo === "b" ? 700 : "inherit" }}>{txt}</span>;
    }
    return <span key={i}>{p}</span>;
  });
}

function PreviewCalendario({ dados, linhas, foto }) {
  return (
    <div style={{ ...PV.frameOuter, borderColor: "#7a1122" }}>
      <div style={{ padding: 12 }}>
        <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 8 }}>
          <img src={foto} alt="Ilustração" style={{ width: 120, borderRadius: 4 }} />
          <div style={{ flex: 1, textAlign: "right" }}>
            <div style={{ color: TEMPLATE.azul, fontWeight: 800, fontSize: 20, lineHeight: 1.1 }}>Calendário de pregação</div>
            <div style={{ color: TEMPLATE.azul, fontWeight: 700, fontSize: 12, marginTop: 6 }}>{dados.congregacao}</div>
            <div style={{ color: TEMPLATE.azul, fontWeight: 700, fontSize: 12 }}>{dados.mesAno}</div>
          </div>
        </div>

        {dados.mostrarFaixa && (<>
          <div style={{ background: TEMPLATE.vinho, color: "#fff", textAlign: "center", fontSize: 9, fontWeight: 700, padding: "3px 4px" }}>{dados.faixaTitulo}</div>
          <div style={{ background: "#9a1b2f", color: "#fff", textAlign: "center", fontSize: 8, fontStyle: "italic", padding: "2px 4px", marginBottom: 4 }}>{dados.faixaSub}</div>
        </>)}

        <table style={{ width: "100%", borderCollapse: "collapse", tableLayout: "fixed", marginTop: dados.mostrarFaixa ? 0 : 4 }}>
          <thead><tr>{DIAS_SEMANA.map((d) => <th key={d} style={CAL.pvHead}>{d}</th>)}</tr></thead>
          <tbody>
            {linhas.map((linha, li) => (
              <tr key={li}>
                {linha.map((c, ci) => (
                  <td key={ci} style={{ ...CAL.pvCell, background: c ? (c.cor || "#fff") : "#f4f5f7" }}>
                    {c ? <><div style={CAL.pvNum}>{c.numero}</div><div style={CAL.pvTexto}>{renderTextoDia(c.texto)}</div></> : null}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>

        <div style={{ marginTop: 8 }}>
          {dados.notas.map((n) => (
            <div key={n.id} style={{ fontSize: 7.5, lineHeight: 1.4, marginBottom: 2, color: n.tipo === "titulo" ? "#c0392b" : "#333", fontStyle: n.tipo === "titulo" ? "italic" : "normal", fontWeight: n.tipo === "titulo" ? 700 : 400 }}>{n.texto}</div>
          ))}
        </div>
      </div>
    </div>
  );
}


/* ====================== TELA CARTÃO DE DESIGNAÇÕES ====================== */

// ---- extração do PDF anotado (roda no navegador via pdf.js) ----
// Os nomes anotados em azul não fazem parte do texto normal da página — são
// anotações "FreeText" sobrepostas ao PDF original (um jeito comum de
// preencher esses formulários). Por isso extraímos duas coisas separadas:
// (1) o texto estrutural da apostila (títulos, durações, cabeçalhos) e
// (2) as anotações, cada uma com sua posição na página — depois associamos
// cada designado ao item numerado mais próximo dele na mesma página.
//
// Esse PDF também desenha alguns acentos como um caractere avulso flutuando
// acima da letra (não como marca combinante do Unicode), o que quebraria a
// leitura por linha; por isso ignoramos esses marcadores e trabalhamos com o
// texto estrutural sem acento (as anotações com os nomes, essas sim, vêm com
// acentuação correta).
const ACENTO_SOLTO_RE = /^[ʰ-˿¨´¸`~]+$/;

async function extrairPDFCartao(file) {
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
  const linhas = []; // { texto, y, page }
  const anotacoes = []; // { texto, y, x, page, usada }

  for (let p = 1; p <= pdf.numPages; p++) {
    const page = await pdf.getPage(p);
    const content = await page.getTextContent();
    let atual = "", atualY = null, atualEndX = null;
    const flush = () => { if (atual) linhas.push({ texto: atual, y: atualY, page: p }); };
    for (const it of content.items) {
      const texto = it.str;
      if (!texto) continue;
      if (ACENTO_SOLTO_RE.test(texto)) continue;
      const x = it.transform[4], y = it.transform[5];
      const largura = it.width || 0;
      const altura = it.height || 10;
      if (atualY === null) { atual = texto; atualY = y; atualEndX = x + largura; continue; }
      if (Math.abs(y - atualY) > 2) {
        flush();
        if (Math.abs(y - atualY) > 16) linhas.push({ texto: "", y: atualY, page: p });
        atual = texto; atualY = y; atualEndX = x + largura;
      } else {
        const gap = x - atualEndX;
        atual += (gap > altura * 0.2 ? " " : "") + texto;
        atualEndX = x + largura;
      }
    }
    flush();
    linhas.push({ texto: "", y: null, page: p });

    const anns = await page.getAnnotations();
    for (const a of anns) {
      const texto2 = ((a.contentsObj && a.contentsObj.str) || "").trim();
      if (texto2 && a.rect) {
        anotacoes.push({
          texto: texto2,
          y: (a.rect[1] + a.rect[3]) / 2,
          x: (a.rect[0] + a.rect[2]) / 2,
          page: p, usada: false,
        });
      }
    }
  }

  const offsets = [];
  let acumulado = 0;
  for (const l of linhas) {
    offsets.push({ offset: acumulado, y: l.y, page: l.page });
    acumulado += l.texto.length + 1;
  }
  const texto = linhas.map((l) => l.texto).join("\n").normalize("NFD").replace(/[̀-ͯ]/g, "");
  return { texto, offsets, anotacoes };
}

function posicaoDoOffset(offsets, alvo) {
  let lo = 0, hi = offsets.length - 1, res = offsets[0];
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (offsets[mid].offset <= alvo) { res = offsets[mid]; lo = mid + 1; } else hi = mid - 1;
  }
  return res;
}

function achaAnotacaoProxima(anotacoes, pos, distMax) {
  let melhor = null, melhorDist = Infinity;
  for (const a of anotacoes) {
    if (a.usada || a.page !== pos.page || pos.y == null) continue;
    const dist = Math.abs(a.y - pos.y);
    if (dist < melhorDist && dist < distMax) { melhor = a; melhorDist = dist; }
  }
  return melhor;
}

function novoIdCartao() { return Date.now() + Math.random(); }

// Alguns trechos-chave (Cântico, oração, Comentários…) caem justamente nas
// palavras estilizadas com o acento avulso, então sobra às vezes um espaço
// extra onde o acento ficava. Este helper monta um regex tolerante a esse
// espaço solto entre letras.
function tolerantePalavra(palavra) {
  return palavra.split("").map((c) => c.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("[ \\t]{0,2}");
}
const T_CANTICO = tolerantePalavra("Cantico");
const T_ORACAO = tolerantePalavra("oracao");
const T_COMENTARIOS = tolerantePalavra("Comentarios");
const T_INICIAIS = tolerantePalavra("iniciais");
const T_PALAVRA = tolerantePalavra("PALAVRA");
const T_DE = tolerantePalavra("DE");
const T_DEUS = tolerantePalavra("DEUS");
const T_VIDA = tolerantePalavra("VIDA");
const T_CRISTA = tolerantePalavra("CRISTA");

const RE_ABRE_SEMANA = new RegExp(`${T_CANTICO}[ \\t]+(\\d+)[ \\t]+e[ \\t]+${T_ORACAO}[ \\t]+${T_COMENTARIOS}[ \\t]+${T_INICIAIS}`, "g");
const RE_FECHAMENTO = new RegExp(`${T_CANTICO}[ \\t]+(\\d+)[ \\t]+e[ \\t]+${T_ORACAO}(?![ \\t]*${T_COMENTARIOS})`, "g");
const RE_PALAVRA_DE_DEUS = new RegExp(`${T_PALAVRA}[ \\t]+${T_DE}[ \\t]+${T_DEUS}`, "g");
const RE_VIDA_CRISTA = new RegExp(`${T_VIDA}[ \\t]+${T_CRISTA}`, "g");
const RE_ITEM = /(?:^|[\s·])(\d{1,2})\.[ ]+((?:(?!\(\d{1,2}\s*min\)|\d{1,2}\.[ ])[\s\S]){1,90})\((\d{1,2})\s*min\)/g;

// Lê o PDF anotado e devolve um rascunho de semanas. É um reconhecimento "de
// melhor esforço": datas, lição da leitura e alguma parte tipo "Consideração"
// costumam precisar de ajuste manual na prévia antes de aplicar.
function processarCartaoPDF({ texto, offsets, anotacoes }) {
  const aberturas = [...texto.matchAll(RE_ABRE_SEMANA)];
  const semanas = [];

  for (let w = 0; w < aberturas.length; w++) {
    const abre = aberturas[w];
    const inicio = abre.index;
    const fim = w + 1 < aberturas.length ? aberturas[w + 1].index : texto.length;

    const linhasBloco = texto.slice(inicio, fim).split("\n").map((l) => l.trim());
    let presidente = "";
    for (let i = 1; i < linhasBloco.length && i < 40; i++) {
      if (/^\d{1,3}$/.test(linhasBloco[i])) {
        let j = i - 1;
        while (j >= 0 && !linhasBloco[j]) j--;
        const cand = linhasBloco[j];
        if (cand && cand.split(" ").length <= 4 && !/\d/.test(cand) && /^[A-Z][a-zA-Zç\s./]*$/.test(cand)) {
          presidente = cand;
          break;
        }
      }
    }
    const annPresidente = achaAnotacaoProxima(anotacoes, posicaoDoOffset(offsets, inicio), 60);
    if (annPresidente) { presidente = annPresidente.texto.trim(); annPresidente.usada = true; }

    RE_FECHAMENTO.lastIndex = inicio;
    const mFecha = RE_FECHAMENTO.exec(texto);
    let canticoFinal = "", oracaoFinal = "";
    if (mFecha && mFecha.index < fim) {
      canticoFinal = mFecha[1];
      const annFecha = achaAnotacaoProxima(anotacoes, posicaoDoOffset(offsets, mFecha.index), 40);
      if (annFecha) { oracaoFinal = annFecha.texto.trim(); annFecha.usada = true; }
    }

    RE_ITEM.lastIndex = inicio;
    const itens = [];
    let m;
    while ((m = RE_ITEM.exec(texto)) && m.index < fim) {
      const numero = Number(m[1]);
      const titulo = m[2].replace(/\s+/g, " ").trim();
      if (titulo && numero >= 1 && numero <= 15) {
        const pos = posicaoDoOffset(offsets, m.index + m[0].length);
        const ann = achaAnotacaoProxima(anotacoes, pos, 40);
        itens.push({ numero, titulo, designado: ann ? ann.texto.trim() : "", posicao: m.index });
        if (ann) ann.usada = true;
      }
    }

    // parte 1 (tema principal) costuma ter o nome colado no cabeçalho
    // "PALAVRA DE DEUS" em vez de junto da própria duração
    const item1 = itens.find((i) => i.numero === 1);
    if (item1 && !item1.designado) {
      RE_PALAVRA_DE_DEUS.lastIndex = inicio;
      const mPD = RE_PALAVRA_DE_DEUS.exec(texto);
      if (mPD && mPD.index < fim) {
        const annPD = achaAnotacaoProxima(anotacoes, posicaoDoOffset(offsets, mPD.index), 40);
        if (annPD) { item1.designado = annPD.texto.trim(); annPD.usada = true; }
      }
    }

    RE_VIDA_CRISTA.lastIndex = inicio;
    const mVC = RE_VIDA_CRISTA.exec(texto);
    const posVidaCrista = mVC && mVC.index < fim ? mVC.index : -1;

    const ministerioItens = [], vidaCristaItens = [];
    for (const it of itens) {
      if (it.numero <= 3) continue;
      if (posVidaCrista !== -1 && it.posicao > posVidaCrista) vidaCristaItens.push(it);
      else ministerioItens.push(it);
    }

    const tema1 = itens.find((i) => i.numero === 1);
    const joias = itens.find((i) => i.numero === 2);
    const leitura = itens.find((i) => i.numero === 3);

    semanas.push({
      id: novoIdCartao(), semReuniao: false, motivo: "",
      dataLabel: "", leituraBiblica: "",
      presidente, canticoInicial: abre[1], oracaoInicial: presidente, oracaoManual: false,
      tema1Titulo: tema1 ? tema1.titulo : "", tema1Designado: tema1 ? tema1.designado : "",
      joiasDesignado: joias ? joias.designado : "",
      leituraLicao: "", leituraDesignado: leitura ? leitura.designado : "",
      ministerio: ministerioItens.map((i) => ({ id: novoIdCartao(), titulo: i.titulo, detalhe: "", designado: i.designado })),
      canticoMeio: "",
      vidaCrista: vidaCristaItens.map((i) => ({ id: novoIdCartao(), titulo: i.titulo, detalhe: "", designado: i.designado })),
      canticoFinal, oracaoFinal,
    });
  }
  return semanas;
}

function novaSemanaCartao() {
  return {
    id: novoIdCartao(), semReuniao: false, motivo: "",
    dataLabel: "", leituraBiblica: "",
    presidente: "", canticoInicial: "", oracaoInicial: "", oracaoManual: false,
    tema1Titulo: "", tema1Designado: "",
    joiasDesignado: "",
    leituraLicao: "", leituraDesignado: "",
    ministerio: [{ id: novoIdCartao(), titulo: "", detalhe: "", designado: "" }],
    canticoMeio: "",
    vidaCrista: [{ id: novoIdCartao(), titulo: "Estudo bíblico de congregação", detalhe: "", designado: "" }],
    canticoFinal: "", oracaoFinal: "",
  };
}

