  responsaveis: { display: "flex", justifyContent: "center", gap: 26, fontSize: 10, color: "#333", flexWrap: "wrap" },
  aviso: { textAlign: "center", fontSize: 9.5, color: TEMPLATE.vinho, fontStyle: "italic", marginTop: 6 },
