const CSS = `
  * { box-sizing: border-box; }
  textarea:focus, input:focus { outline: 2px solid ` + UI.azul + `; outline-offset: 1px; }
  button:focus-visible { outline: 2px solid ` + UI.azul + `; outline-offset: 2px; }
  button:disabled { opacity: .5; cursor: not-allowed; }
  @media (max-width: 1000px) {
    div[style*="260px 1fr"] { grid-template-columns: 1fr !important; }
    div[style*="repeat(5, 1fr)"] { grid-template-columns: repeat(2, 1fr) !important; }
  }
  @media (max-width: 860px) { .grid { grid-template-columns: 1fr !important; } }
`;
